-- ============================================================
-- base_funcionarios: criação da tabela + carga inicial
-- Execute no Supabase SQL Editor
-- ============================================================

CREATE TABLE IF NOT EXISTS base_funcionarios (
  id               SERIAL PRIMARY KEY,
  matricula        TEXT NOT NULL,
  nome_completo    TEXT NOT NULL,
  maquina          TEXT,
  setor            TEXT,
  categoria        TEXT,
  dias_trabalhados TEXT,
  categoria_bonus  TEXT,
  valor_bonus      NUMERIC(10, 2),
  bonus_atual      NUMERIC(10, 2),
  ativo            BOOLEAN NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE base_funcionarios ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'base_funcionarios'
    AND policyname  = 'autenticado pode tudo em base_funcionarios'
  ) THEN
    EXECUTE 'CREATE POLICY "autenticado pode tudo em base_funcionarios"
      ON base_funcionarios FOR ALL TO authenticated USING (true) WITH CHECK (true)';
  END IF;
END
$$;

ON CONFLICT DO NOTHING;
